import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Module: handl_plugin_ext_refinement","description":"","frontmatter":{},"headers":[],"relativePath":"api/host/handl_plugin_ext_refinement/handl_plugin_ext_refinement.md","filePath":"api/host/handl_plugin_ext_refinement/handl_plugin_ext_refinement.md"}`),a={name:`api/host/handl_plugin_ext_refinement/handl_plugin_ext_refinement.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<p><strong>handl_plugin_ext_refinement</strong></p><h1 id="module-handl-plugin-ext-refinement" tabindex="-1">Module: handl_plugin_ext_refinement <a class="header-anchor" href="#module-handl-plugin-ext-refinement" aria-label="Permalink to “Module: handl_plugin_ext_refinement”">​</a></h1><h2 id="contents" tabindex="-1">Contents <a class="header-anchor" href="#contents" aria-label="Permalink to “Contents”">​</a></h2><p><strong>Modules</strong></p><ul><li><a href="#arrow-lang"><code>arrow_lang</code></a> - Loads the arrow DSL language definition.</li><li><a href="#arrow-loader"><code>arrow_loader</code></a> - File loader: reads <code>.hnl</code> arrow files, parses them into <code>Term</code> IR,</li><li><a href="#arrow-parser"><code>arrow_parser</code></a> - A minimal arrow-graph parser for <code>.hnl</code> arrow files (ADR-0069).</li><li><a href="#checker"><code>checker</code></a> - Runtime axiom checker bridge (ADR-0077 Phase 3).</li><li><a href="#contracts"><code>contracts</code></a> - Contract registry -- the separate registry for base-arrow contracts.</li><li><a href="#inference"><code>inference</code></a> - The refinement inference engine.</li><li><a href="#loader"><code>loader</code></a> - Parser for handl contract files.</li><li><a href="#loop-invariant"><code>loop_invariant</code></a> - Fixpoint loop invariant discovery.</li><li><a href="#partial-eval"><code>partial_eval</code></a> - Partial-evaluator typechecker foundation (ADR-0068, steps 1 &amp; 4).</li><li><a href="#plugin"><code>plugin</code></a> - Plugin integration: <code>Refine</code> operation, <code>RefinementBehavior</code> trait,</li><li><a href="#smt"><code>smt</code></a> - SMT-style implication checker.</li><li><a href="#termination"><code>termination</code></a> - Termination analysis for <code>Term</code> loops.</li><li><a href="#trait-inference"><code>trait_inference</code></a> - Trait inference: annotation-free law recognition (Phase 9).</li><li><a href="#types"><code>types</code></a> - Core refinement types: predicates, refinement types, contracts, and results.</li></ul><hr><h2 id="module-arrow-lang" tabindex="-1">Module: arrow_lang <a class="header-anchor" href="#module-arrow-lang" aria-label="Permalink to “Module: arrow_lang”">​</a></h2><p>Loads the arrow DSL language definition.</p><p>Since ADR-0079, the arrow dialect uses the canonical handl language directly. Arrow-specific keywords (<code>arr</code>, <code>comp</code>, <code>first</code>, <code>choice</code>, <code>loop</code>, <code>app</code>, <code>id</code>) are handled as regular identifiers by the parser, which dispatches on callee names in <code>materialize_node</code>.</p><h1 id="precedence-override" tabindex="-1">Precedence override <a class="header-anchor" href="#precedence-override" aria-label="Permalink to “Precedence override”">​</a></h1><p>The canonical grammar binds <code>&gt;&gt;&gt;</code> (flow, bp 25/26) tighter than <code>|||</code> (choice, bp 20/21). The arrow DSL requires the <strong>opposite</strong>: <code>|||</code> binds tighter than <code>&gt;&gt;&gt;</code> so that <code>a &gt;&gt;&gt; b ||| c</code> parses as <code>a &gt;&gt;&gt; (b ||| c)</code> (= <code>Seq(a, Choice(b, c))</code>). We override the two grammar rows after loading the canonical language to swap their binding powers.</p><h2 id="module-arrow-loader" tabindex="-1">Module: arrow_loader <a class="header-anchor" href="#module-arrow-loader" aria-label="Permalink to “Module: arrow_loader”">​</a></h2><p>File loader: reads <code>.hnl</code> arrow files, parses them into <code>Term</code> IR, resolves cross-file references, and bridges to the inference engine.</p><p>This closes the gap between source files and the inference engine (ADR-0069): a user writes a <code>.hnl</code> file, and <code>infer_file</code> provides the path from that file to <code>infer_refinement(scheme, registry)</code>.</p><h1 id="cross-file-reference-resolution" tabindex="-1">Cross-file reference resolution <a class="header-anchor" href="#cross-file-reference-resolution" aria-label="Permalink to “Cross-file reference resolution”">​</a></h1><p>When a <code>.hnl</code> file references a named arrow (e.g. <code>sort.hnl</code> calls <code>insert(...)</code>), the parser produces an <code>App { callee: arr(&quot;insert&quot;) }</code> node. The loader resolves these by loading the referenced arrow&#39;s file and inlining its <code>Term</code> graph -- matching the hand-built graphs in <code>e2e_tests.rs</code> where <code>sort</code> inlines <code>insert</code>&#39;s full graph.</p><h2 id="module-arrow-parser" tabindex="-1">Module: arrow_parser <a class="header-anchor" href="#module-arrow-parser" aria-label="Permalink to “Module: arrow_parser”">​</a></h2><p>A minimal arrow-graph parser for <code>.hnl</code> arrow files (ADR-0069).</p><p>This parser reads the arrow-graph syntax used in <code>handl-packages/</code> and produces <code>Term</code> IR. It uses the <strong>data-driven</strong> lexer + Pratt parser (driven by the YAML language definition in <code>data/</code>) to build an AST, then materializes the AST into a <code>Term</code> via [<code>ast_to_scheme</code>].</p><h1 id="two-syntaxes" tabindex="-1">Two syntaxes <a class="header-anchor" href="#two-syntaxes" aria-label="Permalink to “Two syntaxes”">​</a></h1><ol><li><p><strong>Simple arrow-graph syntax</strong> — the combinator expressions described in ADR-0069. Supports both function-call syntax and infix operator syntax:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>loop(comp(insert, first(id)))       // function-call syntax</span></span>
<span class="line"><span>loop(insert &gt;&gt;&gt; first(id))          // equivalent operator syntax</span></span>
<span class="line"><span>arr(&quot;sort&quot;)</span></span>
<span class="line"><span>comp(a, b)                          // same as: a &gt;&gt;&gt; b</span></span>
<span class="line"><span>choice(a, b)                        // same as: a ||| b</span></span></code></pre></div><p>The infix operators <code>&gt;&gt;&gt;</code> (sequence) and <code>|||</code> (choice) are sugar: <code>a &gt;&gt;&gt; b</code> desugars to <code>comp(a, b)</code> (<code>Term::Seq</code>), and <code>a ||| b</code> desugars to <code>choice(a, b)</code> (<code>Term::Choice</code>). <code>|||</code> binds tighter than <code>&gt;&gt;&gt;</code>, so <code>a &gt;&gt;&gt; b ||| c</code> parses as <code>comp(a, choice(b, c))</code>.</p></li><li><p><strong>Rich <code>loop { ... } ( params ~&gt; body )</code> syntax</strong> — the surface syntax actually used in the stdlib <code>.hnl</code> files. The YAML grammar tokenizes and parses this syntax into a <code>loop_rich</code> AST node. The <code>ast_to_scheme</code> materializer then pattern-matches on the arrow body&#39;s recursive match arm to determine the corresponding <code>Term</code> graph — the same heuristic as the legacy ad-hoc parser, but operating on the AST instead of raw text.</p></li></ol><h1 id="fallback-strategy" tabindex="-1">Fallback strategy <a class="header-anchor" href="#fallback-strategy" aria-label="Permalink to “Fallback strategy”">​</a></h1><p>The data-driven parser is tried first. If it fails (e.g. for unsupported constructs), the legacy ad-hoc recursive-descent parser is used as a fallback. This ensures existing <code>.hnl</code> files continue to parse correctly. The simple <code>loop(body)</code> form now falls through to the legacy parser because the <code>loop</code> prefix grammar row was changed to handle the rich <code>loop { ... } ( ... )</code> form (arity 2 instead of 1).</p><h2 id="module-checker" tabindex="-1">Module: checker <a class="header-anchor" href="#module-checker" aria-label="Permalink to “Module: checker”">​</a></h2><p>Runtime axiom checker bridge (ADR-0077 Phase 3).</p><p>Bridges the refinement system&#39;s inferred [<code>Contract</code>]s to the [<code>RuntimePredicateChecker</code>] trait, enabling runtime enforcement of <code>requires</code>/<code>guarantee</code> axioms via [<code>OpRegistry::register_with_checker</code>].</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to “Overview”">​</a></h2><p>The refinement inference engine infers [<code>Contract</code>]s (precondition + guarantee predicates) for base arrows and stores them in a [<code>ContractRegistry</code>]. Until Phase 3, these contracts were used only at typecheck/inference time — they were never enforced at runtime.</p><p>This module closes that gap:</p><ul><li>[<code>ContractChecker</code>] wraps a [<code>Contract</code>] as a [<code>RuntimePredicateChecker</code>], evaluating the <code>precondition</code>/<code>guarantee</code> predicates against actual runtime values via [<code>Pred::eval</code>].</li><li>[<code>register_contract_checkers</code>] takes a [<code>ContractRegistry</code>] and an [<code>OpRegistry</code>] and registers a [<code>ContractChecker</code>] for every contract whose op already has a registered <code>Function</code> impl (the handl).</li></ul><p>Once registered, [<code>OpFunction::call</code>] enforces the axioms at the dispatch boundary: <code>requires</code> is checked before the call, <code>guarantee</code> is checked against the return value after the call.</p><h2 id="module-contracts" tabindex="-1">Module: contracts <a class="header-anchor" href="#module-contracts" aria-label="Permalink to “Module: contracts”">​</a></h2><p>Contract registry -- the separate registry for base-arrow contracts.</p><p>Per ADR-0052, contracts do NOT go in <code>Term</code>. They live in a separate registry keyed by <code>(op, source)</code>, mirroring the research prototype&#39;s <code>RefSigEntry</code> table but adapted to handl&#39;s <code>ArrSource</code> discipline.</p><p>Two registries are provided:</p><ul><li>[<code>ContractRegistry::minimal</code>] -- the reduced 3-atom registry modelling only the irreducible Rust primitives (<code>prim.add</code>, <code>prim.compare</code>, <code>prim.alloc</code>). This is the minimal setup used by the extended refinement plugin for Choice WP branching and conditional contracts.</li><li>[<code>ContractRegistry::standard</code>] -- the legacy 18-contract registry ported from the research prototype. Retained for backward compatibility with the existing test suite; new code should prefer <code>minimal()</code>.</li></ul><h2 id="module-inference" tabindex="-1">Module: inference <a class="header-anchor" href="#module-inference" aria-label="Permalink to “Module: inference”">​</a></h2><p>The refinement inference engine.</p><p>Ported from the research prototype&#39;s <code>infer_refinement</code> and <code>infer_r</code> functions, adapted to operate over handl&#39;s <code>Term</code> IR instead of <code>RGraph</code>.</p><p>Mapping from <code>RGraph</code> to <code>Term</code>:</p><ul><li><code>RGraph::Id</code> -&gt; <code>Term::Op { name: &quot;id&quot;, source: Native, .. }</code></li><li><code>RGraph::Comp(g, h)</code> -&gt; <code>Term::Seq { fst: g, snd: h }</code></li><li><code>RGraph::First(g)</code> -&gt; <code>Term::First { inner: g }</code></li><li><code>RGraph::Left(g)</code> -&gt; <code>Term::Choice { l: g, r: identity }</code> (conservatively demoted)</li><li><code>RGraph::Loop(g)</code> -&gt; <code>Term::Loop { body: g }</code></li><li><code>RGraph::Arr(name)</code> -&gt; <code>Term::Op { name: name, source: Native, args: vec![], lit: None }</code></li></ul><h2 id="module-loader" tabindex="-1">Module: loader <a class="header-anchor" href="#module-loader" aria-label="Permalink to “Module: loader”">​</a></h2><p>Parser for handl contract files.</p><p>Reads <code>.hnl</code> contract files and populates a <code>ContractRegistry</code>. This moves axiomatic contracts out of Rust source (<code>contracts.rs</code>) and into handl contract files, so the <code>ContractRegistry</code> becomes a loader that reads these files at startup.</p><h1 id="contract-file-format" tabindex="-1">Contract file format <a class="header-anchor" href="#contract-file-format" aria-label="Permalink to “Contract file format”">​</a></h1><p>Each axiom has the form:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>axiom &lt;name&gt; : &lt;input-type&gt; -&gt; &lt;output-type&gt;   (or \`→\`)</span></span>
<span class="line"><span>  requires: &lt;predicate&gt;      // optional, defaults to True</span></span>
<span class="line"><span>  guarantee: &lt;predicate&gt;     // required</span></span>
<span class="line"><span>  termination: &lt;effect&gt;      // optional</span></span></code></pre></div><h2 id="type-syntax" tabindex="-1">Type syntax <a class="header-anchor" href="#type-syntax" aria-label="Permalink to “Type syntax”">​</a></h2><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>Int                            -&gt; Plain(Int)</span></span>
<span class="line"><span>Bool                           -&gt; Plain(Bool)</span></span>
<span class="line"><span>a, b, c (type variables)       -&gt; Plain(Var(&quot;a&quot;))</span></span>
<span class="line"><span>List T                         -&gt; List(T)</span></span>
<span class="line"><span>(T * T) or (T × T)             -&gt; Prod(T, T)</span></span>
<span class="line"><span>(T + T)                        -&gt; Sum(T, T)</span></span>
<span class="line"><span>{ x : T | pred }               -&gt; Refine(T, pred)</span></span></code></pre></div><h2 id="predicate-syntax" tabindex="-1">Predicate syntax <a class="header-anchor" href="#predicate-syntax" aria-label="Permalink to “Predicate syntax”">​</a></h2><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>True                           -&gt; True</span></span>
<span class="line"><span>False                          -&gt; False</span></span>
<span class="line"><span>Sorted(x)                      -&gt; Sorted(&quot;x&quot;)</span></span>
<span class="line"><span>LengthEq(a, b)                 -&gt; LengthEq(&quot;a&quot;, &quot;b&quot;)</span></span>
<span class="line"><span>LengthLe(a, b)                 -&gt; LengthLe(&quot;a&quot;, &quot;b&quot;)</span></span>
<span class="line"><span>AllSatisfy(list, pred)         -&gt; AllSatisfy(&quot;list&quot;, &quot;pred&quot;)</span></span>
<span class="line"><span>Le(a, b)                       -&gt; Le(&quot;a&quot;, &quot;b&quot;)</span></span>
<span class="line"><span>HeadOf(elem, list)             -&gt; HeadOf(&quot;elem&quot;, &quot;list&quot;)</span></span>
<span class="line"><span>LengthPlusOne(a, b)            -&gt; LengthPlusOne(&quot;a&quot;, &quot;b&quot;)</span></span>
<span class="line"><span>LengthSubOne(a, b)             -&gt; LengthSubOne(&quot;a&quot;, &quot;b&quot;)</span></span>
<span class="line"><span>IsPerm(a, b)                   -&gt; IsPerm(&quot;a&quot;, &quot;b&quot;)</span></span>
<span class="line"><span>p &amp;&amp; q  or  p ∧ q              -&gt; And(p, q)</span></span>
<span class="line"><span>p || q  or  p ∨ q              -&gt; Or(p, q)</span></span>
<span class="line"><span>p ==&gt; q                        -&gt; Implies(p, q)</span></span>
<span class="line"><span>forall x in list, pred         -&gt; Forall(&quot;x&quot;, &quot;list&quot;, &quot;pred&quot;)</span></span></code></pre></div><p>The parser is self-contained (no external parsing crate): it uses simple line-based scanning with a small recursive-descent expression parser for types and predicates.</p><h2 id="module-loop-invariant" tabindex="-1">Module: loop_invariant <a class="header-anchor" href="#module-loop-invariant" aria-label="Permalink to “Module: loop_invariant”">​</a></h2><p>Fixpoint loop invariant discovery.</p><p>Ported from the research prototype&#39;s <code>discover_invariant_fixpoint_real</code> and <code>weakest_precondition</code> functions, adapted to operate over handl&#39;s <code>Term</code> IR instead of <code>RGraph</code>.</p><p>The algorithm:</p><ol><li>Start with <code>I_0 = True</code> (the trivial invariant -- everything is in D).</li><li>Compute the WEAKEST PRECONDITION of the loop body on the feedback channel: <code>wp(G, I)</code> = the weakest predicate on <code>c</code> such that after <code>G</code> executes, <code>I(c&#39;)</code> holds.</li><li>The invariant must be a FIXPOINT: <code>I = wp(G, I) &amp; I</code> (conjunction).</li><li>Iterate: <code>I_{n+1} = I_n &amp;&amp; wp(G, I_n)</code>.</li><li>Stop when <code>I_{n+1} == I_n</code> (fixpoint reached) or after <code>max_iterations</code>.</li></ol><h2 id="module-partial-eval" tabindex="-1">Module: partial_eval <a class="header-anchor" href="#module-partial-eval" aria-label="Permalink to “Module: partial_eval”">​</a></h2><p>Partial-evaluator typechecker foundation (ADR-0068, steps 1 &amp; 4).</p><p>ADR-0068 (&quot;Predicates as Types&quot;) specifies that the typechecker is a <strong>partial evaluator with a termination guard</strong>: to verify a type-position proposition <code>lhs == rhs</code>, the checker normalizes both sides and compares them. If normalization is blocked (a symbolic value it cannot reduce, an effect, non-termination), the checker does <strong>not</strong> fail — it reports [<code>Verdict::Blocked</code>], which the caller treats as &quot;insert a runtime check&quot;. That is the &quot;graduated guarantees&quot; model: proven statically where normalizable, checked at runtime where not.</p><p>Induction principles such as <code>array.rec</code> are library functions the checker <em>recognizes</em>, not syntax. [<code>Arr::Rec</code>] models an <code>array.rec(base, step, goal)</code> region; [<code>recognize_array_rec</code>] recovers its structure and [<code>prove_array_rec</code>] runs structural <strong>induction over the array</strong> with two checker directives:</p><ul><li>[<code>Directive::ByEval</code>] — reduce both sides and compare their normal forms (no induction hypothesis). Used for the <code>base: by_eval</code> case.</li><li>[<code>Directive::ByNorm</code>] — reduce both sides, applying the induction hypothesis as a rewrite, then compare. Used for the <code>step: (x, rest, ih) -&gt; by_norm + ih</code> case.</li></ul><p>The canonical example from ADR-0068 §2 — proving the length lemma</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>array.rec(base: by_eval, step: (x, rest, ih) -&gt; by_norm + ih)</span></span>
<span class="line"><span>  : array.length(append(a, b)) == array.length(a) + array.length(b)</span></span></code></pre></div><p>— is exposed directly as [<code>prove_length_append</code>]; the analogous [<code>prove_length_map</code>] proves <code>|map(f, a)| == |a|</code>.</p><h2 id="module-plugin" tabindex="-1">Module: plugin <a class="header-anchor" href="#module-plugin" aria-label="Permalink to “Module: plugin”">​</a></h2><p>Plugin integration: <code>Refine</code> operation, <code>RefinementBehavior</code> trait, <code>BasicRefiner</code> rule acceptor, and <code>RefinementCore</code> plugin.</p><p>This follows the standard <code>RuleAcceptor</code> plugin pattern:</p><ul><li><code>Refine</code> is the operation marker.</li><li><code>RefineRequest</code> / <code>RefineResult</code> are the request/response types.</li><li><code>RefinementBehavior</code> is the behavior trait for refinement rules.</li><li><code>BasicRefiner</code> is the <code>RuleAcceptor</code> plugin that accepts those rules.</li><li><code>RefinementCore</code> is a <code>Plugin</code> that contributes the canonical refinement rule.</li></ul><h2 id="module-smt" tabindex="-1">Module: smt <a class="header-anchor" href="#module-smt" aria-label="Permalink to “Module: smt”">​</a></h2><p>SMT-style implication checker.</p><p>The implication checker delegates to Z3 (an industrial SMT solver) for genuine validity checking, using the native <code>z3</code> Rust crate (with Z3 statically linked via the <code>static-link-z3</code> feature -- no system library or Python subprocess required). Predicates are translated directly into Z3 ASTs and the validity query is encoded as a satisfiability check of the negation: <code>P ==&gt; Q</code> is VALID iff <code>(P &amp;&amp; !Q)</code> is UNSAT.</p><p>Arithmetic refinements (<code>LengthEq</code>, <code>LengthLe</code>) are encoded with real Int arithmetic, so Z3 performs genuine linear-integer reasoning. Custom refinements (<code>Sorted</code>, <code>AllSatisfy</code>, <code>Forall</code>) are encoded as distinct Boolean atoms -- one per ground predicate -- which is sound: Z3 only reports UNSAT (valid) when the implication holds for <em>every</em> interpretation of those atoms, and never proves a false implication by conflating two distinct predicates.</p><p>If native Z3 returns <code>unknown</code> (rare for these decidable fragments), we fall back to a robust Python-subprocess checker, and finally to the conservative structural (toy) checker, preserving soundness.</p><h2 id="module-termination" tabindex="-1">Module: termination <a class="header-anchor" href="#module-termination" aria-label="Permalink to “Module: termination”">​</a></h2><p>Termination analysis for <code>Term</code> loops.</p><p>Ported from the research prototype&#39;s <code>analyze_termination</code>, <code>analyze_loop_termination</code>, and <code>analyze_comp_loop_termination</code> functions, adapted to operate over handl&#39;s <code>Term</code> IR.</p><p>The <code>Loop</code> combinator <code>loop G : A ~&gt; B</code> where <code>G : A*C ~&gt; B*C</code> repeatedly applies <code>G</code>, threading <code>C</code> through as feedback. Termination requires that <code>C</code> has a well-founded measure that decreases each iteration.</p><p>Cases handled:</p><ol><li>Side-channel loop (<code>loop(first(G))</code>) -- C unchanged -&gt; NOT GUARANTEED</li><li>List-consuming loop (<code>loop(seq(process, consume_one))</code>) -- |C| decreases -&gt; GUARANTEED</li><li>Counter loop (<code>loop(seq(step, decrement))</code>) -- C decreases -&gt; GUARANTEED</li><li>Fixed-point loop (<code>loop(seq(f, id))</code>) -- no decreasing measure -&gt; NOT GUARANTEED</li><li>Nested loop (<code>loop(seq(loop(inner), first(id)))</code>) -- depends on inner</li><li>Nested loop with non-terminating inner -- NOT GUARANTEED</li><li>Map (no loop) -- direct termination</li><li>Sort via loop (<code>loop(seq(insert, remove_one))</code>) -- |C| decreases -&gt; GUARANTEED</li></ol><h2 id="module-trait-inference" tabindex="-1">Module: trait_inference <a class="header-anchor" href="#module-trait-inference" aria-label="Permalink to “Module: trait_inference”">​</a></h2><p>Trait inference: annotation-free law recognition (Phase 9).</p><p>This module is the Rust mirror of the Lean4 formalization in <code>research/arrow-calculus-kernel-poc/lean/ArrowMinimalityLib/TraitInference.lean</code>.</p><p>The Lean4 file proves that a graph&#39;s wiring structure alone — without any trait declaration — determines which equational laws it satisfies. The key concepts are:</p><ul><li><code>Law</code> — a named equational law (functor identity, functor composition, coproduct functor identity, coproduct functor composition).</li><li><code>UsesFirst</code> / <code>UsesLeft</code> — structural recognizers that detect whether a graph uses the <code>first</code> (product functor) or <code>left</code> (coproduct functor) combinator anywhere in its wiring.</li><li><code>SatisfiesLaw</code> — a graph <code>G</code> satisfies <code>law</code> when (1) G&#39;s wiring exhibits the structural pattern the law applies to, and (2) the law is verified (both sides normalize to the same canonical form). In the Rust port, law verification is taken as proven (the Lean4 proofs have zero <code>sorry</code>), so <code>SatisfiesLaw</code> reduces to the structural-pattern check.</li><li><code>inferred_trait</code> — the set of laws inferred from a graph&#39;s wiring, by structural recursion. This is the annotation-free trait inference: the system inspects the graph and returns the laws it satisfies.</li></ul><h1 id="mapping-from-lean4-graph-to-rust-term" tabindex="-1">Mapping from Lean4 <code>Graph</code> to Rust <code>Term</code> <a class="header-anchor" href="#mapping-from-lean4-graph-to-rust-term" aria-label="Permalink to “Mapping from Lean4 Graph to Rust Term”">​</a></h1><p>The Lean4 <code>Graph</code> type has constructors <code>idG</code>, <code>arr</code>, <code>comp</code>, <code>first</code>, <code>left</code>, <code>loop</code>. The Rust <code>Term</code> type has <code>Arr</code>, <code>Seq</code>, <code>First</code>, <code>Choice</code>, <code>Loop</code>, <code>App</code>. The correspondence is:</p><table tabindex="0"><thead><tr><th>Lean4 <code>Graph</code></th><th>Rust <code>Term</code></th></tr></thead><tbody><tr><td><code>Graph.first F</code></td><td><code>Term::First { inner: F }</code></td></tr><tr><td><code>Graph.left F</code></td><td><code>Term::Choice { l: F, r }</code></td></tr><tr><td><code>Graph.comp G H</code></td><td><code>Term::Seq { fst: G, snd: H }</code></td></tr><tr><td><code>Graph.loop G</code></td><td><code>Term::Loop { body: G }</code></td></tr><tr><td><code>Graph.idG A</code></td><td><code>Term::arr_native(&quot;id&quot;, [])</code></td></tr><tr><td><code>Graph.arr f</code></td><td><code>Term::Op { name: f, .. }</code></td></tr></tbody></table><p>The <code>left</code> combinator (coproduct functor) maps to <code>Term::Choice</code> in the Rust IR. In the Lean4 formalization, <code>left F</code> routes <code>Left</code> through <code>F</code> and <code>Right</code> through the identity — this is <code>Choice { l: F, r: id }</code> in the Rust IR. The <code>UsesLeft</code> recognizer therefore checks for <code>Choice</code> nodes where the left branch is the &quot;active&quot; sub-graph (the right branch is the pass-through identity).</p><h2 id="module-types" tabindex="-1">Module: types <a class="header-anchor" href="#module-types" aria-label="Permalink to “Module: types”">​</a></h2><p>Core refinement types: predicates, refinement types, contracts, and results.</p><p>These are ported from the research prototype&#39;s <code>refinement_inference_tests.rs</code>, <code>termination_analysis_tests.rs</code>, and <code>real_programs_tests.rs</code>, adapted to be self-contained (no dependency on the research crate).</p>`,92)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};